from pathlib import Path
import json,html,re
B=Path(__file__).parent;D=B/'DX.5';F=D/'fragments';F.mkdir(exist_ok=True)
REFNUM={x['id']:str(n+1) for n,x in enumerate(json.loads((D/'paquet.json').read_text())['passages'])}
def p(t,ids):
 for y in ['2010','2024','2026']:
  if y in t:ids+=' flu-date-'+y
 if 'SARS-CoV-2' in t:ids+=' flu-ssi-tests'
 refs=''.join('<sup class="r"><a href="#sb-'+i+'">'+REFNUM.get(i,i)+'</a></sup>' for i in dict.fromkeys(ids.split()))
 ss=re.split(r'(?<=[.!?])\s+(?=[A-ZÀ-Ý«])',t)
 out=''
 for v in ss:
  punct=v[-1] if v[-1:] in '.!?' else '.'
  body=v[:-1] if v[-1:] in '.!?' else v
  out+=html.escape(body)+refs+punct+' '
 return '<div class="p">'+out+'</div>\n'
def prose(t,ids):return ''.join(p(x.strip(),ids) for x in t.strip().split('\n') if x.strip())
def tab(head,rows):return '<div class="t" style="overflow-x:auto"><table><thead><tr>'+''.join('<th>'+html.escape(x)+'</th>' for x in head)+'</tr></thead><tbody>\n'+''.join('<tr>'+''.join('<td>'+p(c,r)+'</td>' for c in cs)+'</tr>\n' for cs,r in rows)+'</tbody></table></div>\n'
N={}
def w(n,title,t,ids):
 N[n]=N.get(n,0)+1;k=f'dx5-p{n}-w{N[n]}'
 return '<p><button class="w" popovertarget="'+k+'">'+html.escape(title)+'</button></p><div class="fenetre" popover id="'+k+'"><h4>'+html.escape(title)+'</h4>'+prose(t,ids)+'</div>\n'
def put(n,t):(F/f'p{n:02}.html').write_text(t)
put(1,prose('''La grippe saisonnière est une infection contagieuse due aux virus influenza circulant dans la population, dont les manifestations sont principalement respiratoires et générales.
L’OFSP décrit une maladie infectieuse fréquente en hiver, causée par les virus influenza A et B. L’ECDC retient également une maladie contagieuse à symptômes surtout respiratoires.
La définition clinique doit être séparée de la confirmation étiologique : fièvre, toux et myalgies forment une présentation compatible, sans identifier à elles seules le virus responsable.
La SSI, dans sa recommandation validée en septembre 2026 sur les infections respiratoires aiguës de l’adulte, souligne que les plaintes générales peuvent dominer la présentation grippale.
Le motif « douleurs musculaires » reste donc compatible avec une infection respiratoire même si le patient décrit surtout des courbatures, des céphalées et un malaise.
Une forme peu fébrile chez une personne âgée n’exclut pas cette infection. L’absence d’un signe typique ne remplace pas l’évaluation du terrain et de l’état général.''','flu-ofsp-12 flu-ofsp-14 flu-ofsp-17 flu-ssi-definition')+tab(['Terme','Sens clinique','Conséquence'],[
(['La grippe saisonnière désigne une infection influenza.','Les virus A et B constituent les causes décrites par l’OFSP.','Un test moléculaire identifie l’étiologie quand cette information modifie la conduite.'],'flu-ofsp-14 flu-ssi-tests'),
(['Le syndrome grippal décrit un regroupement de plaintes.','Les douleurs, la toux, les céphalées et la fièvre éventuelle peuvent accompagner plusieurs infections.','La présentation syndromique ne suffit pas à choisir un antiviral spécifique.'],'flu-ssi-definition flu-ssi-tests'),
(['Une grippe non sévère ne présente pas de manifestation de gravité.','La définition OMS résumée en 2026 inclut les formes avec ou sans fièvre.','L’absence de gravité doit être réévaluée si l’évolution change.'],'flu-oms-cadre'),
(['La grippe sévère peut nécessiter une hospitalisation.','Elle comprend pneumonie sévère, sepsis, défaillances ou décompensation d’une maladie chronique.','Le lieu de prise en charge dépend de la complication et du retentissement.'],'flu-oms-cadre')])+
w(1,'Myalgie, arthralgie et faiblesse','''Une myalgie est une douleur ressentie dans les muscles ; une arthralgie concerne une articulation. Ces deux plaintes sont décrites dans la grippe par l’OFSP.
Le patient qui se dit faible peut décrire un malaise ou une limitation par la douleur. Le clinicien doit préciser la fonction plutôt que transformer ce mot en diagnostic de lésion musculaire.
La présence de myalgies dans un syndrome grippal ne démontre pas, à elle seule, une myosite ou une rhabdomyolyse.''','flu-ofsp-17 flu-ssi-definition')+
w(1,'Le mot saisonnière décrit un contexte','''L’OFSP rapporte une circulation surtout pendant la saison froide dans les zones tempérées. Les épisodes ne sont pas identiques d’une année à l’autre.
Cette saisonnalité augmente la plausibilité clinique, mais elle ne fournit pas une confirmation individuelle. La SSI demande d’intégrer les données épidémiologiques à la décision de tester.
Une exposition animale particulière demande de vérifier un autre cadre de surveillance ; elle ne doit pas être automatiquement classée comme grippe saisonnière.''','flu-ofsp-21 flu-ssi-tests flu-oms-cadre')+
prose('''Le terme refroidissement est souvent utilisé pour une infection virale banale. L’OFSP rappelle que la grippe peut être légère et confondue avec cette présentation, mais qu’elle peut aussi entraîner des complications sévères.
La vaccination antigrippale protège contre influenza dans les limites de son efficacité ; elle ne protège pas contre toutes les causes de rhume ni contre le SARS-CoV-2.
Le raisonnement évite ainsi deux raccourcis : considérer toute courbature fébrile comme une grippe confirmée, ou écarter la grippe parce que le patient est vacciné.''','flu-ofsp-17 flu-ofsp-18 flu-ofsp-36 flu-ofsp-37'))
put(2,prose('''Les données suisses doivent être lues avec leur dénominateur. L’OFSP estime que la grippe entraîne chaque année entre 50 000 et 250 000 consultations médicales, selon le système Sentinella.
Ce nombre mesure une charge de consultations estimée ; il ne correspond ni à tous les sujets infectés, ni à une prévalence instantanée, ni au bilan déjà connu de la saison en cours.
La même page décrit plusieurs milliers d’hospitalisations et fréquemment plusieurs centaines de décès dus aux complications. Elle ne fournit pas de valeur unique applicable à chaque hiver.
Les personnes âgées, les femmes enceintes, les prématurés et les personnes atteintes de maladies chroniques sont particulièrement concernés par les complications.
La possibilité de complications chez un jeune adulte auparavant en bonne santé reste réelle, bien que rare selon l’OFSP ; le terrain favorable ne dispense donc pas d’examiner les signes de gravité.''','flu-ofsp-22 flu-ofsp-19')+
tab(['Mesure','Population et période','Interprétation'],[
(['L’OFSP rapporte 50 000 à 250 000 consultations par année.','Il s’agit d’estimations suisses issues de Sentinella présentées sur la page courante consultée en 2026.','La plage traduit la variabilité ; elle ne doit pas être transformée en cas confirmés virologiquement.'],'flu-ofsp-22'),
(['L’ECDC estime que jusqu’à 20 % de la population est infectée chaque année.','La page européenne décrit le fardeau saisonnier général, sans fixer ici une saison de référence unique.','Cette proportion d’infections ne peut pas être directement comparée au nombre suisse de consultations.'],'flu-ecdc-definition'),
(['L’OFSP donne une incubation d’environ un à trois jours.','La période sépare la contamination de l’apparition des manifestations.','Une exposition récente compatible aide l’anamnèse sans constituer un critère de confirmation.'],'flu-ofsp-15'),
(['L’ECDC donne une moyenne de deux jours, avec une plage d’un à quatre jours.','Il s’agit du cadre descriptif européen de la page consultée.','La différence de plage avec l’OFSP reste attribuée à chaque source ; aucun seuil diagnostique rigide n’en est déduit.'],'flu-ecdc-definition')])+
prose('''La fréquence des consultations dépend aussi de la saison, de l’accès aux soins et de la définition utilisée pour surveiller les syndromes respiratoires.
Une incidence suisse chiffrée de toutes les infections, incluant les personnes qui ne consultent pas, n’est pas fournie par les sources acquises. Cette limite interdit de convertir les consultations Sentinella en risque individuel exact.
Les sources utilisées ne donnent pas de rapport hommes-femmes suisse applicable à toutes les saisons. Le sexe ne doit donc pas servir de coefficient de probabilité inventé.
Dans les zones tempérées, la circulation augmente surtout pendant les mois froids. L’OFSP relève l’exception de l’hiver 2020/21, sans épidémie de grippe dans le contexte des mesures contre la pandémie de COVID-19.''','flu-ofsp-21 flu-ofsp-22')+
w(2,'Évolution habituelle et prolongation des symptômes','''L’OFSP indique qu’une grippe peut durer jusqu’à deux semaines. L’ECDC précise que les manifestations générales d’une forme adulte non compliquée durent souvent quelques jours.
La toux, la fatigue et la sensation de malaise peuvent persister plusieurs semaines selon l’ECDC. Une durée prolongée de toux ne démontre donc pas automatiquement une persistance de réplication nécessitant un antiviral.
Une détérioration respiratoire, une hypotension ou une altération importante de l’état général impose cependant une nouvelle évaluation, même si une convalescence prolongée était attendue.''','flu-ofsp-17 flu-ecdc-definition flu-ssi-alarmes')+
w(2,'Vulnérabilité et gravité actuelle répondent à deux questions','''L’âge avancé ou une immunodépression augmentent le risque d’évolution défavorable. Ils influencent la décision de tester et la discussion d’un traitement précoce.
La gravité actuelle est appréciée par l’état général, la pression artérielle, la fréquence respiratoire, l’oxygénation et les signes de complication.
Un patient à haut risque peut être momentanément stable ; inversement, un patient sans comorbidité peut présenter une pneumonie sévère nécessitant une hospitalisation.''','flu-ssi-alarmes flu-ssi-decision-antiviraux flu-oms-cadre')+
prose('''Les enjeux de santé publique associent la prévention vaccinale, la réduction de la transmission et la reconnaissance des complications. La prescription d’un antiviral ne remplace aucun de ces axes.
Les estimations générales servent à comprendre l’importance de la maladie. Les décisions d’un jour donné doivent aussi prendre en compte les données contemporaines de circulation virale et les délais réels d’accès au test.''','flu-ofsp-25 flu-ssi-tests'))
put(3,prose('''Les virus influenza sont des virus enveloppés à ARN simple brin segmenté de polarité négative. Le séminaire HUG de décembre 2024 situe cette structure dans la famille des Orthomyxoviridae.
La multiplication virale dans les voies respiratoires constitue l’amorce de la maladie. La présence de matériel génétique viral peut être recherchée par amplification moléculaire sur un prélèvement respiratoire adapté.
La revue de Peiris et collaborateurs publiée en 2010 relie l’infection et les lésions des cellules épithéliales respiratoires aux symptômes respiratoires. Elle relie notamment l’IL-6, le TNF-α et les interférons aux manifestations générales telles que fièvre et myalgies.
Cette chaîne distingue la douleur musculaire généralisée d’une destruction musculaire prouvée. Une plainte de courbatures ne permet pas de conclure à une atteinte nécrosante du muscle.
Le mécanisme immunitaire peut expliquer des symptômes à distance du site respiratoire. Il ne justifie pas un dosage de cytokines dans le bilan ambulatoire recommandé par la SSI.
L’exploration utile cherche plutôt à identifier le virus lorsque le résultat change la décision, puis à mesurer le retentissement respiratoire et circulatoire lorsque le tableau paraît compliqué.''','flu-hug-virus flu-pathogenese flu-ssi-tests')+
tab(['Perturbation','Exploration qui informe la décision','Intervention et mécanisme'],[
(['La réplication produit du matériel génétique influenza.','Une PCR respiratoire recherche la séquence virale ; elle ne mesure pas à elle seule la gravité.','Le baloxavir inhibe l’endonucléase dépendante de la coiffe et freine la transcription virale.'],'flu-ssi-tests aips-flu-xofluza-mecanisme'),
(['La neuraminidase facilite la libération des particules nouvellement formées.','La confirmation virologique distingue influenza d’autres causes de syndrome grippal.','Le métabolite actif de l’oseltamivir inhibe les neuraminidases des virus A et B.'],'aips-flu-tamiflu-mecanisme flu-ssi-tests'),
(['L’infection de l’épithélium et la réponse inflammatoire provoquent des symptômes respiratoires.','L’examen recherche dyspnée, accélération respiratoire et anomalies focales d’auscultation.','Le niveau de soins est adapté au retentissement ; une pneumonie sévère relève d’une prise en charge hospitalière.'],'flu-pathogenese flu-ssi-tests flu-oms-cadre'),
(['Les médiateurs inflammatoires contribuent aux manifestations générales.','L’anamnèse décrit fièvre, myalgies et malaise ; l’examen vérifie les constantes et la fonction.','Les soins symptomatiques visent le confort et la capacité à boire, sans confondre amélioration symptomatique et éradication virale.'],'flu-pathogenese flu-ecdc-prevention'),
(['Une infection bactérienne secondaire peut compliquer l’épisode.','Le bilan est orienté par la dyspnée, les anomalies focales et les marqueurs inflammatoires dans le cadre SSI.','Une antibiothérapie est discutée pour une complication bactérienne probable, pas pour toute PCR influenza positive.'],'flu-pathogenese flu-ssi-tests flu-ssi-antibiotiques-non')])+
w(3,'Deux cibles antivirales distinctes','''L’oseltamivir est un promédicament transformé en carboxylate d’oseltamivir. L’inhibition de la neuraminidase agit surtout sur la libération et la propagation des particules virales.
Le baloxavir marboxil est également un promédicament. Son métabolite inhibe l’endonucléase dépendante de la coiffe, une activité du complexe polymérase viral nécessaire à la transcription.
Les cibles différentes expliquent que les deux médicaments ne soient pas interchangeables sur la base d’un nombre de comprimés. Leur indication, leur durée et leurs adaptations suivent leurs notices respectives.''','aips-flu-tamiflu-mecanisme aips-flu-xofluza-mecanisme aips-flu-tamiflu-4 aips-flu-xofluza-4')+
w(3,'Inflammation ne signifie pas corticothérapie systématique','''Les cytokines participent à la maladie, mais cette explication mécanistique ne démontre pas un bénéfice clinique des corticoïdes contre la grippe.
La SSI ne trouve pas de preuve soutenant leur utilisation dans les infections respiratoires aiguës sans indication respiratoire sous-jacente identifiée.
L’OMS émet une recommandation conditionnelle contre les corticoïdes comme traitement adjuvant de la grippe sévère. Une autre indication doit être distinguée de la seule infection influenza.''','flu-pathogenese flu-ssi-symptomatique flu-oms-diagnostic')+
prose('''La phase d’installation associe les manifestations locales et la réponse générale. La persistance de toux ou de fatigue après amélioration n’est pas nécessairement le reflet d’une réplication encore sensible à un traitement tardif.
Dans une maladie sévère, une atteinte pulmonaire, une infection bactérienne associée ou la décompensation d’un terrain chronique peuvent entretenir les symptômes. La surveillance ne se limite donc pas à la température.
L’OFSP cite aussi la myocardite et les complications neurologiques. Une douleur thoracique inhabituelle ou une modification de l’état neurologique doit faire rechercher une complication, au lieu d’être automatiquement attribuée aux courbatures.
La revue mécanistique utilisée compare également des grippes pandémiques et zoonotiques. Les résultats expérimentaux de ces cadres ne sont pas transformés ici en fréquence ou en traitement de la grippe saisonnière courante.
L’apparition d’une résistance antivirale est possible, notamment lors de réplication prolongée. Les HUG rappellent que des mutations distinctes peuvent diminuer la sensibilité à l’oseltamivir ou au baloxavir.
La SSI recommande une discussion infectiologique en cas d’immunodépression ; cette discussion évite de prolonger ou de combiner empiriquement les médicaments sans évaluation du contexte.''','flu-ecdc-definition flu-oms-cadre flu-ofsp-18 flu-hug-resistance flu-ssi-decision-antiviraux'))
put(4,prose('''La première décision porte sur le niveau de soins. Une hypothèse de grippe ne doit pas retarder l’évaluation d’une détresse respiratoire, d’un état de choc ou d’une complication neurologique.
La SSI recommande d’envisager une hospitalisation lorsque l’impression clinique globale est défavorable, que la pression systolique est inférieure à 90 mmHg, que la fréquence respiratoire atteint 30 par minute ou que la saturation est inférieure à 92 %.
Ces seuils appartiennent à la recommandation adulte sur les infections respiratoires aiguës. Ils ne constituent pas un score pédiatrique ni une garantie de sécurité lorsque toutes les valeurs sont légèrement au-dessus des limites.
Une hémoptysie, un stridor, une maladie pulmonaire sévère ou une immunodéficience sévère renforcent également l’indication d’une évaluation hospitalière.
Après cette étape, le clinicien distingue une infection influenza plausible, une autre infection respiratoire, une pneumonie ou une complication extrarespiratoire. Les examens sont choisis pour modifier une décision concrète.''','flu-ssi-alarmes flu-ssi-tests flu-ofsp-18')+
tab(['Diagnostic ou complication','Élément discriminant','Piège','Conduite'],[
(['Une grippe sévère ou une pneumonie compliquée menace la fonction respiratoire.','La dyspnée, la saturation, la fréquence respiratoire et l’examen pulmonaire déterminent le retentissement.','Une fièvre modérée ou absente n’élimine pas la gravité chez le sujet âgé.','Le patient est orienté vers une évaluation hospitalière si les signes de gravité sont présents.'],'flu-ssi-alarmes flu-ofsp-17 flu-oms-cadre'),
(['Une infection bactérienne secondaire peut accompagner influenza.','La recherche de signes focaux et les marqueurs inflammatoires sont interprétés dans le cadre clinique SSI.','Une PCR influenza positive n’exclut pas une autre infection associée.','La complication présumée est explorée et traitée selon le protocole de pneumonie approprié.'],'flu-ofsp-18 flu-ssi-tests flu-ssi-antibiotiques-non'),
(['Une infection par SARS-CoV-2 peut imiter la grippe.','Un test moléculaire spécifique est utile si son résultat change la prise en charge du patient à risque.','La vaccination contre influenza ne protège pas contre le SARS-CoV-2.','Le résultat oriente vers la filière thérapeutique et préventive correspondante.'],'flu-ssi-tests flu-ofsp-37'),
(['Une complication cardiaque ou neurologique peut dominer le tableau.','Les symptômes inhabituels doivent être rapprochés de l’examen ciblé et du retentissement général.','Le mot courbatures peut détourner l’attention d’une douleur thoracique ou d’un changement neurologique.','La complication est évaluée sans attendre une simple évolution spontanément favorable.'],'flu-ofsp-18 flu-oms-cadre')])+
w(4,'La gravité est évaluée avant la confirmation','''Une PCR peut préciser l’étiologie, mais elle ne remplace pas les constantes ni l’examen.
Si l’état respiratoire ou circulatoire est préoccupant, l’orientation et les mesures de soutien sont organisées pendant le prélèvement et l’attente du résultat.
Le cadre ambulatoire de la SSI demande un test avant une prescription antivirale ; cette recommandation ne doit pas être utilisée pour différer l’assistance à un patient instable.''','flu-ssi-alarmes flu-ssi-tests flu-oms-cadre')+
w(4,'Les myalgies ne résument pas l’examen musculaire','''Le clinicien demande ce que la douleur empêche : marcher, se lever, boire ou simplement se sentir à l’aise.
Une limitation par douleur doit être distinguée d’un déficit fonctionnel inhabituel. Le syndrome grippal décrit par la SSI comprend des myalgies, mais ne définit pas une maladie musculaire spécifique.
Une plainte qui sort du tableau habituel conduit à reconsidérer le diagnostic plutôt qu’à multiplier automatiquement les antalgiques.''','flu-ssi-definition flu-ofsp-17 flu-ssi-alarmes')+
prose('''Les infections localisées peuvent modifier l’orientation initiale. La SSI renvoie vers les démarches spécifiques lorsque dominent une douleur de gorge, une otalgie ou une douleur sinusienne localisée.
Le choix d’un test doit tenir compte du délai de rendu. Un résultat obtenu après la fenêtre utile d’un antiviral ambulatoire n’a pas le même intérêt décisionnel qu’une PCR moléculaire rapide disponible immédiatement.
La consultation évite un bilan identique chez tous les patients : absence de gravité, faible probabilité de bénéfice antibiotique et absence d’indication antivirale peuvent conduire à une prise en charge clinique sans examens systématiques.
Cette économie d’examens reste conditionnée à une information claire sur les signes qui imposent de revenir. La décision doit être révisable si l’évolution ne suit pas le scénario attendu.''','flu-ssi-definition flu-ssi-tests flu-ssi-alarmes'))
put(5,prose('''L’entretien commence par la date et, si possible, l’heure de début des manifestations. Cette précision conditionne la possibilité d’un traitement antiviral précoce, dont la fenêtre ne commence pas à l’arrivée au cabinet.
Le clinicien demande si l’installation a été soudaine et quelles plaintes sont apparues ensemble : toux, gorge douloureuse, céphalées, frissons, myalgies ou malaise. Il recherche aussi un contact avec des personnes malades et le contexte de circulation virale.
L’anamnèse vérifie séparément la gêne respiratoire et les capacités quotidiennes. Une personne qui décrit surtout des courbatures peut minimiser une aggravation de sa respiration ou de sa maladie chronique.
Chez une personne âgée, l’absence de fièvre rapportée ne rassure pas à elle seule. L’OFSP et la SSI décrivent des présentations atypiques dans cette population.
Les nausées, les vomissements et la diarrhée peuvent accompagner la grippe de l’enfant. Leur présence impose néanmoins de vérifier le retentissement et la possibilité d’une prise orale.
L’histoire d’une grossesse, d’une naissance prématurée ou d’une maladie chronique modifie l’appréciation du risque. Ces informations ne doivent pas être réduites à une simple case administrative.''','flu-ofsp-15 flu-ofsp-17 flu-ofsp-19 flu-ssi-definition flu-ssi-tests')+
tab(['Question ciblée','Pourquoi la poser','Conséquence'],[
(['Depuis quand les premiers symptômes sont-ils présents ?','La fenêtre d’un antiviral ambulatoire est liée au début des symptômes.','Le délai réel est documenté avant toute prescription.'],'aips-flu-tamiflu-3 aips-flu-xofluza-4'),
(['La respiration est-elle devenue plus difficile ?','Une atteinte pulmonaire ou une décompensation peut changer le niveau de soins.','La plainte déclenche la mesure des constantes et un examen respiratoire ciblé.'],'flu-ssi-tests flu-oms-cadre'),
(['Existe-t-il une maladie pulmonaire, cardiaque, neurologique ou une immunodépression ?','La vulnérabilité influence le risque d’évolution sévère et la discussion thérapeutique.','Le médecin adapte les examens, le suivi et le recours spécialisé.'],'flu-ssi-decision-antiviraux'),
(['Une grossesse ou un allaitement est-il en cours ?','Le terrain et les données de sécurité des antiviraux ne sont pas identiques.','La balance bénéfice-risque est examinée pour le produit précis.'],'flu-ofsp-19 aips-flu-tamiflu-8 aips-flu-xofluza-8'),
(['Quels médicaments et compléments sont réellement pris ?','La fonction rénale influence l’oseltamivir ; les cations polyvalents réduisent l’exposition au baloxavir.','La prescription évite les associations ou modalités incompatibles.'],'aips-flu-tamiflu-4 aips-flu-xofluza-7')])+
tab(['Drapeau rouge','Signification','Action immédiate'],[
(['🚩 Le patient paraît globalement très malade.','L’impression clinique peut refléter une complication non encore caractérisée.','Une évaluation hospitalière est envisagée sans attendre la confirmation virologique.'],'flu-ssi-alarmes'),
(['🚩 Une dyspnée, une hémoptysie ou un bruit inspiratoire inhabituel est décrit.','Le tableau peut dépasser une infection respiratoire simple.','Le médecin examine immédiatement la respiration et décide de l’orientation.'],'flu-ssi-alarmes flu-ssi-tests'),
(['🚩 Une douleur thoracique ou une modification neurologique accompagne l’épisode.','L’OFSP reconnaît des complications myocardiques et neurologiques.','La complication est évaluée dans une filière adaptée à sa gravité.'],'flu-ofsp-18 flu-oms-cadre'),
(['🚩 Une maladie pulmonaire ou une immunodéficience sévère est connue.','Le terrain rend une évolution compliquée plus préoccupante.','La décision d’hospitalisation et l’avis infectiologique sont discutés précocement.'],'flu-ssi-alarmes flu-ssi-decision-antiviraux')])+
w(5,'Préciser les traitements déjà pris','''Le médecin recherche les noms des produits, leurs doses et l’heure de la dernière prise. Une baisse de température après un traitement symptomatique ne démontre pas l’absence de complication.
Pour l’oseltamivir, les antécédents rénaux et la dernière évaluation de fonction rénale orientent la dose. Pour le baloxavir, les antiacides et compléments contenant calcium, fer, magnésium, zinc ou sélénium sont particulièrement pertinents.
Une hypersensibilité antérieure au produit ou à un excipient constitue une information décisive avant la première administration.''','aips-flu-tamiflu-4 aips-flu-tamiflu-5 aips-flu-xofluza-5 aips-flu-xofluza-7')+
w(5,'La vaccination ne clôt pas l’enquête','''Le statut vaccinal contribue à la prévention et au contexte, mais l’efficacité varie avec les saisons et les personnes.
Une personne vaccinée peut donc présenter une grippe. Le clinicien conserve la même recherche de signes de complication.
L’entretien vérifie aussi la présence de proches vulnérables afin d’organiser les mesures de réduction de transmission et, dans les situations sélectionnées, de discuter une prophylaxie.''','flu-ofsp-36 flu-ecdc-prevention aips-flu-tamiflu-3'))
put(6,prose('''Le repère normal est un patient capable de parler sans gêne respiratoire inhabituelle, dont la respiration reste aisée et dont l’examen ne révèle pas de foyer pulmonaire ni de défaillance générale apparente.
Ces observations décrivent un examen rassurant ; elles ne sont pas une règle validée de sortie. La SSI demande d’apprécier l’impression clinique globale et les constantes.
Le médecin observe le patient au repos avant de multiplier les gestes. Il recherche une gêne à parler, un effort respiratoire, un bruit inspiratoire ou une coloration inhabituelle, puis confronte l’observation aux mesures.
La fréquence respiratoire doit être réellement comptée et exprimée par minute. Une impression visuelle de respiration rapide ne remplace pas la valeur documentée qui permet d’appliquer les seuils SSI.
La saturation est mesurée dans des conditions permettant un signal exploitable. Une valeur incohérente avec l’état clinique doit être vérifiée plutôt que considérée isolément comme normale.
La pression artérielle et le pouls complètent cette évaluation. Une mesure anormale est interprétée avec les symptômes et l’examen, sans retarder l’orientation d’un patient instable.''','flu-ssi-alarmes flu-ssi-tests')+
tab(['Région ou fonction','Geste pratique','Anomalie recherchée et limite'],[
(['L’état général est évalué dès le contact.','Le clinicien observe la parole, le comportement, la mobilité et la capacité à participer à l’entretien.','Une impression globale défavorable constitue un motif SSI d’envisager l’hospitalisation, même avant un diagnostic complet.'],'flu-ssi-alarmes'),
(['La respiration est examinée au repos.','Les mouvements respiratoires sont comptés et la valeur est notée par minute ; la saturation est relevée avec son contexte.','La SSI retient une fréquence d’au moins 30/min ou une saturation inférieure à 92 % parmi les critères de gravité adultes.'],'flu-ssi-alarmes'),
(['Le thorax est ausculté de façon comparative.','Le stéthoscope est déplacé sur des zones correspondantes afin de rechercher une anomalie localisée.','Des anomalies focales ou des crépitants modifient la décision de rechercher une pneumonie ; une auscultation seule ne précise pas le virus.'],'flu-ssi-tests'),
(['La circulation est appréciée par les constantes et l’état global.','La pression systolique et la fréquence cardiaque sont mesurées et confrontées à l’observation.','Une pression systolique inférieure à 90 mmHg est un signal de gravité ; une tachycardie contribue à la décision de bilan inflammatoire.'],'flu-ssi-alarmes flu-ssi-tests'),
(['L’examen ORL suit la plainte dominante.','La gorge, les oreilles ou les sinus sont évalués lorsque les symptômes les désignent.','Une douleur localisée dominante peut faire sortir de la démarche de syndrome grippal général.'],'flu-ssi-definition')])+
w(6,'Deux seuils respiratoires, deux décisions','''Dans la recommandation SSI adulte, une fréquence respiratoire d’au moins 22/min fait partie des critères conduisant à envisager un marqueur inflammatoire chez un patient avec toux aiguë.
Une fréquence d’au moins 30/min figure parmi les signaux de gravité faisant envisager une hospitalisation.
Ces seuils servent donc des décisions différentes. La première valeur n’est pas un seuil de sortie et la seconde n’interdit pas d’hospitaliser un patient préoccupant avant de l’atteindre.''','flu-ssi-tests flu-ssi-alarmes')+
w(6,'Normalité pulmonaire et limites de l’auscultation','''L’examen rassurant ne retrouve pas de signe focal inquiétant ni d’effort respiratoire inhabituel. Il est rapproché de la saturation et de la fréquence respiratoire.
La SSI considère les anomalies focales comme un motif de bilan chez le patient avec toux aiguë. L’absence de ce signe ne suffit pas à identifier influenza ni à exclure toute complication.
Une réévaluation est nécessaire lorsque les symptômes s’aggravent ou que l’impression clinique ne correspond pas aux premières mesures.''','flu-ssi-tests flu-ssi-alarmes')+
prose('''L’examen musculaire décrit la distribution des douleurs et la fonction. Le patient explique quels mouvements déclenchent la gêne ; le médecin observe les gestes utiles au quotidien sans attribuer toute limitation à une lésion musculaire.
Une plainte articulaire dominante, une douleur localisée ou un déficit inhabituel conduit à reconsidérer le diagnostic. Les myalgies grippales restent un symptôme dans un ensemble respiratoire et général.
Le médecin consigne les valeurs et les conditions de mesure plutôt qu’un simple commentaire « constantes bonnes ». Cette précision rend possible une comparaison lors du suivi.
Les critères SSI cités concernent l’adulte. Leur application brute à un nourrisson, à un jeune enfant ou à une situation obstétricale spécifique serait une extrapolation injustifiée ; ces patients suivent une évaluation adaptée.''','flu-ssi-definition flu-ofsp-17 flu-ssi-alarmes'))
put(7,prose('''Point 7.1 — Le syndrome respiratoire aigu associe des symptômes tels que toux, gorge douloureuse, rhinorrhée ou gêne respiratoire. Le patient décrit les symptômes ; l’examen recherche surtout leur retentissement et les signes focaux.
Point 7.2 — Le syndrome général grippal comporte un début souvent soudain, des céphalées, des frissons, des douleurs musculaires ou articulaires et un malaise. La température peut être élevée, mais la fièvre n’est pas obligatoire.
Point 7.3 — La présentation respiratoire compliquée associe une plainte de dyspnée à des anomalies objectives éventuelles : fréquence respiratoire élevée, désaturation ou anomalie auscultatoire. Elle fait rechercher une atteinte pulmonaire ou une décompensation.
Point 7.4 — La défaillance générale regroupe les manifestations qui rendent une simple prise en charge symptomatique insuffisante : état général très altéré, hypotension ou complication d’organe. Elle impose un changement de niveau de soins.
Ces regroupements servent à organiser l’examen. Ils ne constituent pas un score validé de grippe, et aucun n’identifie à lui seul le virus influenza.''','flu-ssi-definition flu-ofsp-17 flu-ssi-alarmes flu-oms-cadre')+
tab(['Syndrome','Signes fonctionnels','Signes physiques et décision'],[
(['Le tableau respiratoire simple peut être compatible avec influenza.','Le patient rapporte toux, rhinorrhée ou douleur de gorge.','L’examen apprécie les constantes et recherche une anomalie focalisée ; le test dépend de son utilité thérapeutique.'],'flu-ssi-definition flu-ssi-tests'),
(['Le tableau général peut dominer la consultation pour myalgies.','Les douleurs, céphalées et sensations de malaise peuvent être plus marquées que la toux.','La température est mesurée, tout en sachant qu’une personne âgée peut rester afébrile.'],'flu-ssi-definition flu-ofsp-17'),
(['Le tableau pulmonaire préoccupant demande une recherche de complication.','La dyspnée ou l’hémoptysie signale un retentissement inhabituel.','Une saturation basse ou une respiration accélérée modifie immédiatement l’orientation.'],'flu-ssi-alarmes flu-ssi-tests'),
(['La défaillance systémique relève d’une évaluation urgente.','Le récit peut être limité par l’état du patient.','L’hypotension et l’impression clinique défavorable font envisager l’hospitalisation.'],'flu-ssi-alarmes flu-oms-cadre')])+
w(7,'Toux : définition et recherche','''La toux est une expulsion brusque d’air, ressentie et rapportée par le patient. L’entretien précise son début, son caractère et son association à une gêne respiratoire.
Le clinicien observe son retentissement et écoute le thorax lorsque la présentation le justifie. La présence d’une toux n’identifie pas influenza.
Dans la démarche SSI, la toux aiguë est rapprochée de la fièvre, de la dyspnée, de la fréquence respiratoire et de l’auscultation pour décider d’un bilan inflammatoire.''','flu-ssi-definition flu-ssi-tests')+
w(7,'Dyspnée : symptôme et mesure ne sont pas synonymes','''La dyspnée est une sensation de difficulté respiratoire. Elle se recherche par une question directe sur la respiration au repos et pendant les activités habituelles.
La fréquence respiratoire et la saturation sont des mesures objectives complémentaires ; une plainte ne doit pas être écartée parce qu’une mesure isolée paraît acceptable.
La SSI classe la dyspnée parmi les indications d’évaluation supplémentaire et décrit des seuils de gravité pour la respiration et l’oxygénation.''','flu-ssi-tests flu-ssi-alarmes')+
w(7,'Myalgie : une douleur, pas une preuve de nécrose','''Le patient localise les douleurs ressenties dans les muscles et précise leur diffusion. Le clinicien rapproche cette plainte des manifestations respiratoires et de la chronologie.
Les médiateurs inflammatoires contribuent aux myalgies dans la grippe. Cette explication ne démontre pas une destruction musculaire chez chaque patient douloureux.
Une limitation fonctionnelle inhabituelle conduit à réexaminer la situation plutôt qu’à considérer le mot grippe comme une réponse suffisante.''','flu-ofsp-17 flu-pathogenese flu-ssi-alarmes')+
w(7,'Fièvre et frissons : rechercher sans imposer','''La fièvre est une élévation mesurée de la température corporelle ; les frissons sont une sensation accompagnée de contractions musculaires involontaires.
Le clinicien demande la température réellement mesurée et les traitements déjà pris, puis mesure lui-même si nécessaire. La sensation de fièvre n’est pas identique à une mesure.
L’OFSP décrit fréquemment une température supérieure à 38 °C, mais rappelle que les personnes âgées peuvent ne pas présenter de fièvre. Ce seuil descriptif ne constitue pas une condition obligatoire du diagnostic.''','flu-ofsp-17')+
w(7,'Hémoptysie et stridor : deux alarmes différentes','''L’hémoptysie correspond à l’émission de sang provenant des voies respiratoires lors de la toux. Elle doit être distinguée d’un saignement buccal ou nasal rapporté comme crachat sanglant.
Le stridor est un bruit respiratoire évocateur d’un obstacle des voies aériennes supérieures, recherché dès l’observation de la respiration.
La SSI retient chacun de ces signes parmi les situations où une hospitalisation doit être envisagée ; ils ne sont pas des manifestations banales à banaliser dans une grippe supposée.''','flu-ssi-alarmes')+
prose('''La combinaison des syndromes guide le parcours : symptômes généraux et respiratoires sans retentissement sévère orientent vers l’évaluation ambulatoire ; une défaillance respiratoire ou circulatoire impose une autre filière.
L’absence de tous les signes classiques n’exclut pas influenza. Elle impose surtout de ne pas utiliser une définition syndromique comme un test virologique.
La surveillance garde les mêmes repères : apparition d’une gêne respiratoire, détérioration générale ou nouvelle manifestation d’organe font reconsidérer la classification initiale.''','flu-ssi-definition flu-ssi-alarmes flu-oms-cadre'))
put(8,prose('''Le diagnostic positif distingue une hypothèse clinique compatible d’une infection influenza documentée. La SSI recommande une PCR lorsque l’identification du virus détermine une prescription antivirale.
Le contexte épidémique, le début soudain et l’association de plaintes générales et respiratoires augmentent la plausibilité. Ils ne fournissent pas une preuve étiologique indépendante du test.
Il n’existe pas, dans les sources acquises, de score suisse de confirmation individuelle associant un nombre obligatoire de critères majeurs et mineurs. Une telle grille ne doit pas être inventée.
La recommandation SSI de septembre 2026 s’applique à l’infection respiratoire aiguë de l’adulte, définie par des symptômes depuis au plus 21 jours sans autre explication. Cette durée délimite son champ et n’est pas une durée obligatoire de grippe.
La confirmation moléculaire doit être rapprochée du tableau clinique. Elle répond à la question du virus recherché ; elle ne classe pas automatiquement la sévérité et ne remplace pas la recherche de complication.''','flu-ssi-definition flu-ssi-tests flu-oms-cadre')+
tab(['Élément','Ce qu’il soutient','Ce qu’il ne suffit pas à établir'],[
(['Un début soudain avec myalgies, toux et symptômes généraux est compatible.','L’ensemble correspond à la présentation décrite par l’OFSP.','Il ne distingue pas de façon certaine influenza d’une autre infection respiratoire.'],'flu-ofsp-17 flu-ssi-tests'),
(['La circulation épidémique rend influenza plus plausible.','La SSI demande de prendre en compte les données de surveillance.','Le contexte ne dispense pas d’un test lorsque celui-ci conditionne un antiviral.'],'flu-ssi-tests'),
(['Une PCR positive documente la présence de la cible influenza recherchée.','Elle apporte une confirmation microbiologique utile à la conduite.','Elle n’exclut pas une complication bactérienne ou une autre cause associée.'],'flu-ssi-tests flu-ofsp-18'),
(['L’absence de manifestation sévère permet une classification non sévère.','Le cadre OMS sépare cette situation des formes nécessitant souvent l’hôpital.','Cette classification initiale ne garantit pas l’absence d’aggravation ultérieure.'],'flu-oms-cadre'),
(['L’absence de fièvre est possible chez la personne âgée.','Elle explique une présentation atypique.','Elle ne démontre pas l’absence d’infection ni l’absence de gravité.'],'flu-ofsp-17 flu-ssi-definition')])+
w(8,'Critère de surveillance et diagnostic individuel','''Une définition utilisée pour repérer les infections respiratoires ou les syndromes grippaux dans une population facilite la surveillance.
La décision clinique porte sur une personne, son terrain et les conséquences du résultat. Elle doit conserver les présentations atypiques que manquerait une définition trop rigide.
La SSI recommande de tester selon l’utilité attendue et le contexte, en privilégiant la méthode moléculaire pour influenza chez l’adulte.''','flu-ssi-definition flu-ssi-tests')+
w(8,'Pourquoi un test antigénique adulte négatif ne clôt pas le dossier','''La SSI ne recommande pas les tests antigéniques rapides pour influenza chez l’adulte en raison de leurs performances diagnostiques limitées dans cette population.
Un résultat négatif d’une telle méthode ne doit donc pas remplacer la démarche moléculaire indiquée par le contexte thérapeutique.
La rapidité d’un test n’est utile que si sa performance et son délai permettent une décision pertinente ; une PCR moléculaire au point de soins peut répondre à cet objectif quand elle est disponible.''','flu-ssi-tests')+
prose('''Les catégories de risque de progression ne sont pas des critères diagnostiques. L’âge, l’immunodépression et les maladies chroniques influencent le bénéfice attendu d’une intervention sans prouver l’infection.
De même, la réponse à un traitement symptomatique n’identifie pas le virus. Une amélioration de la douleur ou de la température doit rester séparée de la confirmation virologique.
La sortie d’un parcours de grippe simple est décidée lorsque des signes de complication apparaissent. Le diagnostic initial peut rester correct tout en devenant insuffisant pour expliquer l’ensemble de la situation.
La documentation finale indique donc ce qui est établi : tableau compatible, résultat microbiologique éventuel, niveau de gravité, terrain et décision de suivi.''','flu-ssi-decision-antiviraux flu-ssi-tests flu-oms-cadre'))
put(9,prose('''Point 9.a — La méthode de référence utile à la confirmation est la recherche moléculaire du virus sur un prélèvement respiratoire. La SSI demande une PCR influenza chez l’adulte lorsque le résultat conditionne la prescription antivirale.
Le diagnostic clinique suffit à organiser les soins symptomatiques d’une présentation ambulatoire sans indication de test. Il ne constitue cependant pas une confirmation virologique.
Point 9.b — La première intention est guidée par la question à résoudre : identification du virus si elle change la conduite, ou bilan d’une complication si l’examen le suggère.
La demande de laboratoire précise la recherche influenza et le contexte clinique. L’association à une recherche SARS-CoV-2 dépend de l’impact attendu sur la prise en charge, notamment chez un patient à risque.
Le prélèvement et son transport suivent le dispositif validé par le laboratoire. L’heure du début des symptômes et le délai de rendu sont importants, car une prescription ambulatoire précoce peut dépendre d’un résultat rapide.
Un test moléculaire au point de soins peut diminuer ce délai. Son intérêt dépend aussi de sa disponibilité et de son coût ; la rapidité ne justifie pas de substituer un test antigénique adulte que la SSI ne recommande pas.''','flu-ssi-tests flu-oms-diagnostic')+
tab(['Examen','Indication et demande','Interprétation et conduite'],[
(['La PCR influenza est demandée sur un prélèvement respiratoire conforme au laboratoire.','Le résultat doit modifier une décision, en particulier une éventuelle prescription antivirale.','Un résultat positif soutient l’étiologie ; les constantes déterminent séparément la gravité.'],'flu-ssi-tests flu-ssi-alarmes'),
(['La recherche moléculaire SARS-CoV-2 répond à une question distincte.','Elle est indiquée si le résultat change la prise en charge du patient à haut risque.','Un résultat positif conduit à la filière correspondante ; la vaccination influenza ne l’exclut pas.'],'flu-ssi-tests flu-ofsp-37'),
(['La CRP aide à discuter une complication bactérienne dans le cadre SSI adulte.','Elle est envisagée devant toux aiguë avec critères cliniques de probabilité intermédiaire ou élevée.','La valeur est interprétée avec l’examen ; elle ne constitue pas un test de confirmation influenza.'],'flu-ssi-tests'),
(['La radiographie thoracique n’est pas systématique chez l’ambulatoire.','La SSI souligne ses limites pour identifier une consolidation et demande une décision clinique individualisée.','Une suspicion de complication respiratoire peut nécessiter une filière d’imagerie et de soins adaptée.'],'flu-ssi-tests flu-oms-cadre'),
(['L’échographie pulmonaire peut être une alternative diagnostique.','Elle exige un opérateur formé et une question pulmonaire pertinente.','Elle recherche une atteinte pulmonaire ; elle ne fournit pas le nom du virus.'],'flu-ssi-tests')])+
w(9,'Quand demander un marqueur inflammatoire selon la SSI','''Chez un adulte avec toux aiguë, la SSI propose un test en présence d’au moins un des éléments suivants : fièvre mesurée d’au moins 38,5 °C pendant plus de trois jours, dyspnée, fréquence respiratoire d’au moins 22/min, anomalie focale d’auscultation ou pouls d’au moins 100/min.
Ces critères servent à apprécier la probabilité de bénéfice d’un antibiotique. Ils ne sont pas des critères majeurs de grippe.
À l’inverse, la SSI déconseille le dosage chez le patient avec toux aiguë et au moins deux éléments parmi rhinorrhée, gorge douloureuse ou voix rauque, fièvre faible inférieure à 38,5 °C, en l’absence de dyspnée, tachycardie et crépitants.''','flu-ssi-tests')+
tab(['Résultat du cadre SSI adulte','Signification décisionnelle','Conduite et limite'],[
(['Une CRP d’au moins 100 mg/L est retrouvée dans un tableau compatible.','La SSI propose de considérer une antibiothérapie chez le patient présentant les critères cliniques concernés.','Le médecin recherche la complication et utilise la recommandation de pneumonie ; le chiffre seul ne prouve pas une bactérie.'],'flu-ssi-tests'),
(['Une CRP inférieure à 50 mg/L est retrouvée dans le même cadre.','Un traitement symptomatique peut être préféré selon la SSI.','L’état général et les signes de gravité restent prioritaires sur une valeur isolée.'],'flu-ssi-tests flu-ssi-alarmes'),
(['Une CRP entre 50 et 100 mg/L laisse une incertitude.','La recommandation invite à une décision partagée et contextualisée.','Les critères incomplets et l’évolution sont explicités plutôt qu’effacés par un seuil automatique.'],'flu-ssi-tests'),
(['La procalcitonine atteint 0,25 µg/L ou plus.','Elle constitue l’alternative de marqueur mentionnée dans la recommandation.','La SSI précise une limite suisse de remboursement au cabinet pour le point-of-care dans son état de juin 2025.'],'flu-ssi-tests')])+
prose('''Les valeurs de CRP et de procalcitonine ci-dessus sont des seuils de décision issus d’un cadre précis. Elles ne sont pas présentées comme des intervalles universels de normalité biologique.
Le laboratoire fournit ses limites de référence et les unités doivent rester visibles. Les résultats en mg/L pour la CRP et en µg/L pour la procalcitonine ne sont pas interchangeables.
Point 9.c — La grossesse, l’enfance ou l’insuffisance rénale ne transforment pas une PCR respiratoire en examen nécessitant une injection. Le choix du prélèvement et de la méthode suit la population et le laboratoire.
Une allergie à un produit de contraste iodé ou l’impossibilité de réaliser une IRM ne constituent pas, à elles seules, un obstacle à la confirmation moléculaire d’influenza.
L’imagerie n’est demandée que pour une question de complication. Une éventuelle injection de contraste relève alors du protocole de cette indication et de l’évaluation radiologique spécifique ; elle n’est pas requise pour confirmer une grippe simple.
La fonction rénale devient surtout déterminante avant l’oseltamivir. La notice utilise des catégories de clairance de la créatinine : le médecin ne remplace pas automatiquement cette grandeur par une autre estimation rénale sans vérifier son usage.''','flu-ssi-tests aips-flu-tamiflu-4')+
w(9,'Insuffisance rénale : deux usages du bilan à distinguer','''Un bilan rénal peut documenter un terrain ou une complication ; il sert aussi à choisir une dose d’oseltamivir quand ce traitement est indiqué.
La notice distingue les catégories supérieures à 60, supérieures à 30 jusqu’à 60, et de 10 à 30 mL/min de clairance de la créatinine. La dialyse possède ses modalités propres.
Une table de dose n’est pas une indication de traitement. Le clinicien doit d’abord établir le bénéfice attendu, puis appliquer la catégorie rénale pertinente.''','aips-flu-tamiflu-4 flu-ssi-decision-antiviraux')+
prose('''Point 9.d — La deuxième intention dépend de la complication suspectée : bilan pulmonaire, circulatoire, cardiaque ou neurologique selon les manifestations. Il n’existe pas de batterie unique obligatoire pour toute grippe.
Une personne hospitalisée pour maladie sévère peut nécessiter une surveillance et des explorations répétées ; cette situation ne doit pas être confondue avec l’ambulatoire sans signe de gravité.
Une PCR ne remplace pas la recherche de surinfection lorsqu’une complication est plausible. Inversement, l’absence d’argument bactérien ne justifie pas une antibiothérapie préventive systématique.
Les examens supplémentaires doivent toujours être associés à une action possible. Une mesure sans conséquence diagnostique ou thérapeutique identifiable risque de retarder l’information et les soins réellement utiles.''','flu-ofsp-18 flu-oms-cadre flu-ssi-antibiotiques-non flu-ssi-tests'))
put(10,prose('''L’arbre commence par la respiration, la circulation et l’impression clinique. Le résultat virologique n’est pas le premier nœud lorsque le patient paraît instable.
Si un signal SSI de gravité est présent → organiser une évaluation hospitalière et les soins de soutien nécessaires, tout en recherchant la cause et les complications.
Si aucun signal de gravité n’est identifié → préciser le terrain, la chronologie et l’intérêt concret d’un test. Une forme momentanément stable chez un patient vulnérable mérite une décision de suivi explicite.
Si le test ne change ni le traitement ni une autre décision clinique pertinente → privilégier l’évaluation clinique et les mesures symptomatiques, avec consignes de réévaluation.
Si une prescription antivirale est envisagée → rechercher influenza par méthode moléculaire et tenir compte du délai de rendu. La stratégie SSI adulte ne recommande pas le test antigénique rapide.
Si une complication bactérienne est plausible → appliquer la branche d’évaluation respiratoire et de marqueurs inflammatoires appropriée, sans assimiler automatiquement grippe et indication antibiotique.''','flu-ssi-alarmes flu-ssi-tests flu-ssi-antibiotiques-non')+
tab(['Si…','Alors…','Vérification avant la suite'],[
(['Le patient présente une saturation inférieure à 92 %, une fréquence respiratoire d’au moins 30/min ou une pression systolique inférieure à 90 mmHg.','Envisager l’hospitalisation selon l’ensemble clinique.','Ces repères proviennent de la recommandation adulte SSI ; ils ne remplacent pas le jugement en dehors de cette population.'],'flu-ssi-alarmes'),
(['Le patient stable présente une toux aiguë avec dyspnée, anomalie focale ou autres critères SSI.','Discuter le bilan inflammatoire et la recherche d’une pneumonie.','Les résultats sont interprétés avec la clinique et non comme un test de grippe.'],'flu-ssi-tests'),
(['Un adulte ambulatoire a une grippe non compliquée et un risque très élevé de progression.','Discuter le baloxavir précoce selon la recommandation nationale SSI et la décision partagée.','Vérifier le délai, l’indication AIPS, le poids, les interactions, la grossesse et la possibilité d’obtenir le médicament.'],'flu-ssi-decision-antiviraux aips-flu-xofluza-3 aips-flu-xofluza-4 aips-flu-xofluza-8'),
(['Le patient nécessite une hospitalisation pour grippe sévère.','Discuter l’oseltamivir, surtout précocement ; au-delà de 48 heures, individualiser les situations critiques.','La certitude du bénéfice est limitée ; l’insuffisance rénale modifie la dose et les soins de soutien restent prioritaires.'],'flu-ssi-decision-antiviraux aips-flu-tamiflu-4'),
(['Une immunodépression complique le choix thérapeutique.','Contacter l’infectiologue pour discuter stratégie, résistance et éventuelle association.','La combinaison ne devient pas un traitement automatique de toute grippe hospitalisée.'],'flu-ssi-decision-antiviraux')])+
w(10,'Une décision négative doit être expliquée','''Ne pas prescrire un antiviral à un adulte ambulatoire stable ne signifie pas nier la grippe. Cela peut traduire un bénéfice attendu limité, un délai dépassé ou une absence de risque suffisant selon la recommandation utilisée.
Le médecin explique alors les mesures de confort, la réduction de transmission et les signes imposant une réévaluation.
La décision est révisée si le tableau évolue vers une maladie sévère ; la fenêtre du traitement ambulatoire ne doit pas devenir une interdiction de réexaminer une situation critique.''','flu-ssi-decision-antiviraux flu-ecdc-prevention flu-ssi-alarmes')+
w(10,'Un résultat positif ne termine pas l’arbre','''Après confirmation d’influenza, le médecin vérifie encore la gravité, le terrain, l’existence d’une complication et la faisabilité du suivi.
Une PCR positive ne rend pas inutile l’auscultation ni la recherche d’une décompensation de maladie chronique.
Le choix entre traitement symptomatique, antiviral et hospitalisation dépend de ces éléments complémentaires, et non du seul nom du virus.''','flu-ssi-tests flu-oms-cadre flu-ssi-decision-antiviraux')+
prose('''Si le retour à domicile est retenu → vérifier la compréhension des consignes, l’accès au traitement éventuel et la possibilité de demander de l’aide en cas d’aggravation.
Si l’évolution devient défavorable → reprendre le raisonnement au nœud de gravité, plutôt que simplement prolonger une ordonnance antérieure.
L’arbre conserve ainsi deux dimensions : ce qui est établi aujourd’hui et ce qui doit faire modifier la décision demain. Une maladie fréquente peut changer de gravité au cours du même épisode.''','flu-ssi-alarmes flu-ssi-decision-antiviraux flu-oms-cadre'))
put(11,prose('''Point 11.A — Le but est de maintenir une respiration et une circulation stables, de prévenir les complications et de permettre une prise orale et une convalescence compatibles avec le domicile lorsque ce choix reste sûr.
Les seuils SSI adultes de saturation inférieure à 92 %, de fréquence respiratoire d’au moins 30/min et de pression systolique inférieure à 90 mmHg servent de signaux d’orientation. Ils ne constituent pas des objectifs thérapeutiques universels à atteindre par une correction isolée.
Le bénéfice antiviral attendu doit être annoncé avec mesure : la SSI décrit un raccourcissement des symptômes d’environ un jour dans les données ambulatoires et une incertitude importante sur la mortalité dans les formes hospitalisées.
Point 11.B — Les moyens associent le choix du lieu de soins, les mesures symptomatiques, la réduction de transmission et une prescription antivirale sélectionnée. Une antibiothérapie n’est pas indiquée en l’absence d’argument suffisant pour une infection bactérienne associée.''','flu-ssi-alarmes flu-ssi-decision-antiviraux flu-ssi-antibiotiques-non')+
w(11,'Urgence — conduite chronologique','''D’abord, évaluer la respiration, la circulation et l’état général ; les signes de défaillance déclenchent l’organisation d’une prise en charge hospitalière.
Ensuite, obtenir les prélèvements et examens pertinents sans laisser l’attente d’un résultat retarder les soins de soutien nécessaires.
Puis, rechercher la complication responsable : pneumonie sévère, sepsis, décompensation d’une maladie chronique ou autre atteinte d’organe.
En parallèle, discuter l’oseltamivir dans la grippe sévère, en tenant compte du début des symptômes et de la fonction rénale. Une présentation critique tardive nécessite une décision individualisée.
Enfin, organiser la surveillance de l’évolution et l’avis infectiologique dans les situations complexes, notamment l’immunodépression. Le traitement antiviral ne remplace pas le soutien respiratoire ou circulatoire.''','flu-ssi-alarmes flu-oms-cadre flu-ssi-decision-antiviraux aips-flu-tamiflu-4')+
prose('''La recommandation nationale SSI de septembre 2026 ne propose pas un usage routinier du baloxavir chez tous les ambulatoires à haut risque. Son groupe d’experts réserve surtout cette discussion aux personnes à très haut risque, notamment d’au moins 85 ans ou immunodéprimées.
La page locale HOCH validée en janvier 2026 présente une stratégie plus large chez les patients ambulatoires avec facteurs de risque. Ces deux cadres sont attribués séparément ; la prescription n’est pas déduite d’une fusion de leurs tableaux.
L’OMS 2024, résumée dans le BMJ en 2026, formule une recommandation conditionnelle pour le baloxavir dans la grippe non sévère à haut risque et pour l’oseltamivir dans la maladie sévère. Le caractère conditionnel exprime les limites de preuve et la nécessité de contextualiser.
Une autorisation AIPS définit les indications et les modalités du produit ; elle ne démontre pas qu’il faut traiter chaque patient couvert par son libellé. La décision clinique précède le calcul de dose.''','flu-ssi-decision-antiviraux flu-hoch2026 flu-oms-principes aips-flu-xofluza-3 aips-flu-tamiflu-3')+
tab(['Médicament et autorisation','Dose, voie et durée AIPS','Précaution déterminante','Extrait AIPS repérable'],[
(['Tamiflu® contient l’oseltamivir ; autorisations 55196 et 56176.','Chez l’adulte et l’adolescent d’au moins 13 ans avec fonction rénale permettant la dose usuelle : 75 mg par voie orale deux fois par jour pendant cinq jours.','Le traitement est commencé le jour d’apparition ou le lendemain, idéalement dans les 36 heures selon la notice ; adapter à la clairance.','La rubrique Posologie/Mode d’emploi de janvier 2026 décrit le traitement distinct de la prophylaxie.'],'aips-flu-tamiflu-3 aips-flu-tamiflu-4 aips-flu-tamiflu-16 aips-flu-tamiflu-19'),
(['Xofluza® contient le baloxavir marboxil ; autorisations 67426 et 68068.','Pour les comprimés chez un patient d’au moins 20 kg à moins de 80 kg : 40 mg oral en dose unique ; à partir de 80 kg : 80 mg oral en dose unique.','La prise intervient dans les 48 heures ; vérifier le groupe d’âge et l’indication, puis éviter les cations polyvalents concomitants.','Le tableau 1 de juillet 2026 comporte les bornes ≥20 à <80 kg et ≥80 kg.'],'aips-flu-xofluza-3 aips-flu-xofluza-4 aips-flu-xofluza-7 aips-flu-xofluza-16 aips-flu-xofluza-19'),
(['Dafalgan® contient le paracétamol ; autorisations 47503, 47505 et 56318.','La forme effervescente 500 mg permet chez l’adulte de plus de 40 kg 500 à 1000 mg par prise orale, à intervalle de 4 à 8 heures, sans dépasser 4 g/jour en l’absence de facteur imposant une réduction.','La dose maximale est un plafond ; réduire selon terrain, éviter les doublons et respecter les contre-indications hépatiques.','La notice de juillet 2026 indique la douleur légère à modérée et le traitement symptomatique de la fièvre.'],'aips-flu-dafalgan-3 aips-flu-dafalgan-4 aips-flu-dafalgan-5 aips-flu-dafalgan-16 aips-flu-dafalgan-19')])+
w(11,'Tamiflu : traitement et prophylaxie ne se confondent pas','''Le traitement usuel adulte est de 75 mg deux fois par jour pendant cinq jours. La suspension commerciale contient 6 mg/mL ; 75 mg correspondent à 12,5 mL.
La prophylaxie post-exposition adulte utilise 75 mg une fois par jour pendant dix jours, en commençant dans les deux jours suivant le contact. Elle ne doit pas être prescrite au rythme du traitement curatif par simple copie.
Le médicament peut être pris avec ou sans nourriture ; une prise avec des aliments peut améliorer la tolérance digestive.
Les indications de prophylaxie restent sélectionnées selon le risque et le contexte. La prophylaxie médicamenteuse ne remplace pas la vaccination.''','aips-flu-tamiflu-3 aips-flu-tamiflu-4 aips-flu-tamiflu-6')+
tab(['Clairance de la créatinine chez l’adulte','Traitement Tamiflu AIPS','Limite de transposition'],[
(['La clairance est supérieure à 60 mL/min.','La dose usuelle est 75 mg deux fois par jour pendant cinq jours.','Cette ligne concerne le traitement et non la prophylaxie.'],'aips-flu-tamiflu-4'),
(['La clairance est supérieure à 30 et au plus égale à 60 mL/min.','La dose est 30 mg deux fois par jour pendant cinq jours.','Les limites AIPS prévalent sur un tableau local utilisant d’autres bornes.'],'aips-flu-tamiflu-4'),
(['La clairance est comprise entre 10 et 30 mL/min.','La dose est 30 mg une fois par jour pendant cinq jours.','La fréquence change ; reprendre seulement la dose sans le rythme serait insuffisant.'],'aips-flu-tamiflu-4'),
(['La clairance est inférieure à 10 mL/min sans dialyse.','La notice ne fournit pas de recommandation issue d’études dans cette situation.','Un avis spécialisé est nécessaire ; aucune dose n’est extrapolée ici.'],'aips-flu-tamiflu-4'),
(['Le patient bénéficie d’une dialyse.','La notice distingue l’hémodialyse de la dialyse péritonéale et leurs rythmes propres.','La prescription est vérifiée avec l’équipe traitante selon les séances et l’indication.'],'aips-flu-tamiflu-4')])+
w(11,'Tamiflu : traitement pédiatrique autorisé et limite du nourrisson','''Pour le traitement à partir d’un an, la notice prévoit cinq jours avec deux prises quotidiennes : 30 mg si le poids est au plus 15 kg ; 45 mg au-delà de 15 jusqu’à 23 kg ; 60 mg au-delà de 23 jusqu’à 40 kg ; 75 mg au-delà de 40 kg.
Avec la suspension commerciale à 6 mg/mL, ces doses correspondent respectivement à 5 mL, 7,5 mL, 10 mL et 12,5 mL par prise.
L’efficacité et la sécurité ne sont pas établies pour l’usage habituel avant un an dans cette notice. Le schéma particulier de six à douze mois mentionné pour une pandémie ne doit pas être recopié comme prescription de grippe saisonnière.
La notice ne fournit pas de recommandation d’adaptation pour l’enfant insuffisant rénal. Une prise en charge pédiatrique individualisée est nécessaire dans ce cadre.''','aips-flu-tamiflu-3 aips-flu-tamiflu-4')+
w(11,'Xofluza : indication, forme et poids doivent rester associés','''La notice de juillet 2026 autorise le traitement de la grippe non compliquée depuis au plus 48 heures chez les enfants d’au moins trois mois et les adultes par ailleurs en bonne santé, et chez les adolescents d’au moins douze ans et les adultes à haut risque.
La couverture des enfants à haut risque ne doit donc pas être élargie automatiquement à partir du libellé des enfants autrement en bonne santé.
Pour la suspension en flacon à 2 mg/mL, le poids inférieur à 20 kg correspond à une dose unique de 2 mg/kg, soit 1 mL/kg. De 20 à moins de 80 kg, la dose est 40 mg, soit 20 mL ; à partir de 80 kg, elle est 80 mg, soit 40 mL.
Les sachets possèdent un tableau spécifique avec des doses fixes pour certaines plages de poids. Il ne faut pas appliquer leur tableau au flacon ou préparer une suspension à une concentration supposée.
Avant trois mois, les données sont limitées et aucune recommandation posologique n’est formulée dans la notice. Aucune dose n’est inventée pour combler cette limite.''','aips-flu-xofluza-2 aips-flu-xofluza-3 aips-flu-xofluza-4')+
w(11,'Xofluza : interactions et terrains','''La prise concomitante avec boissons enrichies en calcium, antiacides, laxatifs ou compléments contenant des cations polyvalents doit être évitée. Les produits laitiers sont aussi à éviter dans la mesure du possible.
La notice ne recommande pas d’ajustement rénal, tout en indiquant que sécurité et efficacité n’ont pas été évaluées chez les patients ayant des troubles de fonction rénale. L’absence de réduction prescrite n’est pas une preuve de données complètes dans toute insuffisance sévère.
Aucun ajustement n’est requis en atteinte hépatique légère à modérée ; l’atteinte hépatique sévère n’a pas été évaluée.
La grossesse doit conduire à éviter le produit, sauf si le bénéfice potentiel maternel prédomine sur le risque fœtal. Pendant l’allaitement, la décision d’arrêter l’allaitement et d’instaurer le traitement tient compte du bénéfice maternel et du risque pour le nourrisson.''','aips-flu-xofluza-4 aips-flu-xofluza-7 aips-flu-xofluza-8')+
prose('''Pour Tamiflu pendant la grossesse, la notice rapporte des données observationnelles rassurantes mais conserve une prescription en cas d’absolue nécessité après évaluation bénéfice-risque. Aucun ajustement posologique propre à la grossesse n’est prévu.
Pendant l’allaitement, les données de Tamiflu sont limitées et la prescription doit être justifiée par un bénéfice indiscutable. Ces formulations AIPS sont conservées, plutôt que remplacées par une déclaration générale de sécurité absolue.
Chez le sujet âgé, la dose de Tamiflu n’est pas modifiée pour le seul âge ; la fonction rénale doit toutefois être examinée. Une atteinte hépatique légère ou modérée ne demande pas d’ajustement, tandis que les données sont limitées pour l’atteinte sévère.
L’hypersensibilité au principe actif ou aux excipients contre-indique chacun des deux antiviraux. Les excipients diffèrent selon les formes : une solution pratique pour avaler n’est pas automatiquement adaptée à toutes les intolérances héréditaires.''','aips-flu-tamiflu-4 aips-flu-tamiflu-5 aips-flu-tamiflu-6 aips-flu-tamiflu-8 aips-flu-xofluza-5 aips-flu-xofluza-6')+
w(11,'Paracétamol : une prescription symptomatique limitée et vérifiable','''Le paracétamol est destiné au confort et à la fièvre, pas à réduire la réplication d’influenza. La dose est choisie au minimum efficace et réévaluée selon la durée des symptômes.
Dafalgan effervescent 500 mg se dissout dans un grand verre d’eau ; il ne se mâche pas et ne s’avale pas entier. Le comprimé de 1 g n’est pas une forme à diviser pour improviser une petite dose.
Chez l’enfant, la notice demande une dose selon le poids et un intervalle de 6 à 8 heures, avec un plafond quotidien de 75 mg/kg qui ne dispense pas de respecter le plafond plus bas propre à la forme et à la plage de poids.
Chez l’enfant jusqu’à douze ans, l’utilisation continue sans consultation ne dépasse pas trois jours. Une forte fièvre ou une détérioration impose une consultation rapide, sans attendre ce terme.
Il faut additionner le paracétamol de tous les produits pris. La présence d’un médicament contre le rhume ne doit pas masquer une deuxième source du même principe actif.''','aips-flu-dafalgan-3 aips-flu-dafalgan-4 aips-flu-dafalgan-6')+
w(11,'Paracétamol : rein, foie, grossesse et allaitement','''Pour une clairance de créatinine de 10 à 50 mL/min, la notice fixe un intervalle minimal de six heures et un maximum de 3 g/jour. Sous 10 mL/min, l’intervalle est de huit heures et le maximum de 2 g/jour.
En maladie hépatique légère à modérée ou dans certains terrains tels qu’alcoolisme chronique, malnutrition, déshydratation ou cachexie adulte, la dose doit être réduite ou l’intervalle augmenté, avec un maximum de 2 g/jour.
La notice contre-indique les troubles hépatiques graves, l’hépatite aiguë ou maladie hépatique décompensée active, ainsi que la maladie de Gilbert. Une réduction de dose ne contourne pas une contre-indication.
Pendant la grossesse, une nécessité clinique peut justifier le paracétamol à la dose efficace la plus faible, durant la période la plus courte et à la fréquence la plus basse. L’allaitement est considéré compatible, avec prudence.
Une suspicion de surdosage nécessite une évaluation immédiate ; l’absence initiale de symptômes ne permet pas de rassurer sur le risque hépatique.''','aips-flu-dafalgan-4 aips-flu-dafalgan-5 aips-flu-dafalgan-6 aips-flu-dafalgan-8')+
prose('''Les mesures non médicamenteuses associent repos, maintien à domicile pendant la maladie et limitation des contacts. La prise orale et l’aide disponible doivent être vérifiées pour que ces conseils soient réalisables.
Les soins de confort ne doivent pas devenir une accumulation de traitements. La SSI rapporte un bénéfice limité de plusieurs traitements de toux et ne recommande pas une prescription routinière de corticoïdes ou bronchodilatateurs sans indication spécifique.
L’information sociale comprend la possibilité de s’absenter du travail, de réduire les contacts avec des personnes vulnérables et d’obtenir une aide pour les besoins courants. La solution choisie doit rester compatible avec le logement et la situation familiale.
La SSI indique que les antiviraux ne sont généralement pas couverts par l’assurance maladie en Suisse. Le coût, la disponibilité et le bénéfice limité attendu doivent être discutés avant prescription, sans garantir une couverture individuelle non vérifiée.''','flu-ecdc-prevention flu-ssi-symptomatique flu-ssi-decision-antiviraux')+
prose('''Point 11.C — La surveillance porte sur l’état général, la respiration, la capacité à boire, la tolérance des traitements et l’apparition de nouveaux symptômes. Une aggravation conduit à reprendre l’évaluation de gravité.
Sous oseltamivir, des manifestations neuropsychiatriques et convulsives ont été rapportées, notamment chez l’enfant ; la grippe elle-même peut aussi produire ces manifestations. Toute modification préoccupante du comportement nécessite une évaluation.
Une réaction allergique sous antiviral impose une prise en charge appropriée. Sous paracétamol, une réaction cutanée ou un signe d’hypersensibilité impose l’arrêt et une évaluation, conformément à la notice.
La surveillance ne consiste pas à attendre la fin d’une cure de cinq jours si l’état se dégrade. La durée prescrite ne définit pas un délai acceptable avant de demander de l’aide.
Point 11.D — La guérison clinique se traduit par une amélioration durable de l’état général et des symptômes, sans nouvelle complication. Une toux ou une fatigue résiduelle peut persister sans justifier automatiquement un nouvel antiviral.''','flu-ssi-alarmes aips-flu-tamiflu-6 aips-flu-xofluza-6 aips-flu-dafalgan-6 flu-ecdc-definition')+
tab(['Condition de retour ou maintien à domicile','Vérification opérationnelle','Motif de reconsidération'],[
(['Le patient ne présente pas de signe de gravité nécessitant l’hôpital.','L’impression clinique, la respiration et la circulation sont évaluées ensemble.','Une aggravation générale ou un signal SSI impose une nouvelle orientation.'],'flu-ssi-alarmes'),
(['La prise orale et les besoins courants sont réalisables.','Le patient ou son entourage peut suivre les conseils et obtenir une aide si nécessaire.','Une incapacité nouvelle à gérer la situation rend la décision initiale insuffisante.'],'flu-ecdc-prevention flu-ssi-alarmes'),
(['La prescription éventuelle est comprise et accessible.','Le produit, la forme, la dose, le rythme, la durée et les adaptations sont vérifiés.','Une confusion, une indisponibilité ou une intolérance doit être résolue avant de laisser croire le traitement assuré.'],'aips-flu-tamiflu-4 aips-flu-xofluza-4 aips-flu-dafalgan-4'),
(['Les signes de réévaluation ont été expliqués.','La personne sait que dyspnée, altération générale, hémoptysie ou symptôme d’organe inhabituel imposent un nouvel avis.','L’aggravation ne doit pas attendre une échéance administrative ou la fin de l’ordonnance.'],'flu-ssi-alarmes flu-ofsp-18'),
(['Le suivi est adapté au terrain et à l’évolution.','Le médecin précise comment obtenir un avis et individualise un contrôle chez la personne vulnérable.','L’incertitude clinique ou l’absence de possibilité de recours peut modifier le lieu de soins.'],'flu-ssi-decision-antiviraux flu-ssi-alarmes')])+
prose('''Ces conditions de domicile constituent une synthèse opérationnelle des risques et des modalités thérapeutiques ; elles ne sont pas présentées comme un score de sortie validé.
Les sources acquises ne fixent pas un délai universel de contrôle pour toute grippe simple. Le suivi est individualisé et devient immédiat en cas de signal d’alarme.
Un patient ayant été hospitalisé pour maladie sévère suit les critères de sortie de sa complication et de son service. Les critères ambulatoires ne sont pas transposés à une défaillance respiratoire récemment résolue.''','flu-ssi-alarmes flu-oms-cadre'))
put(12,prose('''La prévention primaire repose d’abord sur la vaccination annuelle et les mesures qui réduisent la transmission. L’OFSP la présente comme la prévention la plus simple, efficace et économique contre la grippe.
Les recommandations suisses 2026 conservent les groupes cibles des années précédentes. La vaccination est notamment recommandée aux personnes âgées, aux femmes enceintes, aux prématurés dans le cadre précisé par l’OFSP, aux personnes atteintes de maladies chroniques et à leurs contacts réguliers.
Les professionnels de santé sont concernés par la protection des personnes vulnérables. Le conseil doit également tenir compte des contacts privés et professionnels répétés, plutôt que du seul risque individuel du vacciné.
L’OFSP recommande la période allant de la mi-octobre au début de l’épidémie. Une vaccination antigrippale n’est pas un traitement de l’épisode aigu en cours.
Les produits disponibles et leurs indications doivent être vérifiés pour la saison. La page OFSP courante mentionne des vaccins inactivés intramusculaires et une préférence de haute dose dans certaines catégories âgées à risque.
Cette présentation ne constitue pas une ordonnance vaccinale : la spécialité, l’âge autorisé et le schéma doivent être vérifiés dans la notice AIPS au moment de la prescription.''','flu-ofsp-25 flu-ofsp-26 flu-ofsp-29 flu-ofsp-31')+
tab(['Niveau de prévention','Action concrète','Limite à expliquer'],[
(['La prévention primaire cherche à éviter l’infection ou ses conséquences.','Proposer la vaccination annuelle aux groupes concernés et expliquer les mesures d’hygiène.','L’efficacité varie et aucune protection absolue n’est promise.'],'flu-ofsp-25 flu-ofsp-26 flu-ofsp-36'),
(['La réduction de transmission protège l’entourage.','Rester à domicile pendant la maladie, limiter les contacts, aérer et appliquer l’hygiène respiratoire et des mains.','Un antiviral ne remplace pas ces mesures.'],'flu-ecdc-prevention'),
(['La prévention secondaire repère une évolution défavorable.','Réévaluer rapidement les signes respiratoires ou généraux préoccupants et adapter la filière de soins.','La fréquence de la grippe ne permet pas de banaliser une complication.'],'flu-ssi-alarmes flu-ofsp-18'),
(['La prévention tertiaire limite le retentissement après une maladie compliquée.','Adapter la reprise et le suivi à la complication et à la maladie chronique décompensée.','Une convalescence après hospitalisation ne suit pas automatiquement le parcours d’une grippe légère.'],'flu-oms-cadre flu-ecdc-definition')])+
w(12,'Vaccination : expliquer une efficacité variable','''L’OFSP décrit une efficacité qui varie avec l’âge, l’état de santé et les souches circulantes. Il rapporte une diminution du risque de maladie de 20 à 80 % selon la saison et la personne.
Cette plage n’est pas un chiffre de protection garanti pour un individu. Elle explique pourquoi un cas peut survenir malgré une vaccination correcte.
La vaccination ne protège pas contre les autres virus de refroidissement ni contre le SARS-CoV-2. Le patient conserve donc les mesures de prévention et la recherche de signes de gravité en cas de maladie.''','flu-ofsp-35 flu-ofsp-36 flu-ofsp-37')+
w(12,'Mesures quotidiennes de réduction de transmission','''L’ECDC conseille de réduire les contacts rapprochés avec les personnes malades, de nettoyer les mains et d’éviter de toucher les yeux, le nez ou la bouche.
En présence de symptômes, les mesures comprennent l’hygiène de la toux, le nettoyage des objets et surfaces, l’aération et le maintien à domicile avec limitation des contacts.
Le port d’un masque peut être envisagé dans les espaces fréquentés où la distance ne peut pas être maintenue. Le choix pratique doit tenir compte de la présence de proches vulnérables.
L’OFSP rappelle que la transmission peut précéder la sensation d’être malade ; attendre un tableau complet pour toute prudence ne suffit donc pas.''','flu-ecdc-prevention flu-ofsp-15')+
w(12,'Prophylaxie antivirale : un parcours distinct','''La prophylaxie concerne une personne exposée et non une personne déjà traitée comme malade. La décision tient compte du niveau de risque et du contexte, notamment collectif.
Tamiflu possède un schéma post-exposition différent du traitement : chez l’adulte avec fonction rénale adaptée à la dose usuelle, 75 mg oral une fois par jour pendant dix jours, commencé dans les deux jours du contact.
Xofluza est autorisé en prophylaxie post-exposition dès trois mois, en dose unique pondérale prise au plus vite dans les 48 heures suivant le contact étroit. Il n’est pas indiqué pour la prophylaxie pré-exposition.
Une insuffisance rénale, une grossesse, un allaitement ou une indication pédiatrique exige de reprendre la notice correspondante ; une table curative ne doit pas être réutilisée sans vérification.''','aips-flu-tamiflu-3 aips-flu-tamiflu-4 aips-flu-tamiflu-8 aips-flu-xofluza-3 aips-flu-xofluza-4 aips-flu-xofluza-8')+
prose('''La prévention rejoint les données suisses de charge de maladie : les consultations, hospitalisations et décès ne concernent pas seulement les personnes chez qui une PCR a été réalisée au cabinet.
Les conseils sont adaptés aux conditions de vie. Une personne qui partage son logement avec un proche fragile peut avoir besoin d’une organisation concrète des contacts et d’un soutien pour les besoins quotidiens.
La décision de vaccination future est reprise après l’épisode si le patient appartient à un groupe recommandé. Avoir eu un syndrome grippal non documenté ne démontre pas une protection contre les souches d’une saison ultérieure.''','flu-ofsp-22 flu-ofsp-26 flu-ecdc-prevention'))
put(13,prose('''La grippe saisonnière peut se présenter par des myalgies dominantes, et l’absence de fièvre chez une personne âgée ne l’exclut pas.
La recherche de gravité précède la confirmation virologique ; une détresse respiratoire ou une altération générale change immédiatement le niveau de soins.
Chez l’adulte, la SSI privilégie la PCR lorsque le résultat guide une prescription antivirale et ne recommande pas le test antigénique rapide.
Le choix antiviral dépend du terrain, de la sévérité et du délai ; les doses, formes et adaptations proviennent de la notice AIPS exacte.
Une PCR influenza positive n’exclut pas une complication bactérienne, mais une grippe sans argument de surinfection ne justifie pas un antibiotique systématique.
La vaccination annuelle et les mesures de réduction de transmission restent nécessaires, même lorsqu’un antiviral est prescrit.''','flu-ofsp-17 flu-ssi-alarmes flu-ssi-tests flu-ssi-decision-antiviraux aips-flu-tamiflu-4 aips-flu-xofluza-4 flu-ssi-antibiotiques-non flu-ofsp-25 flu-ecdc-prevention'))
put(14,tab(['Question d’examen','Réponse','Raison clinique'],[
(['Une personne âgée afébrile peut-elle avoir une grippe ?','Oui, l’OFSP décrit cette présentation.','L’absence de fièvre ne remplace pas l’évaluation du contexte et de la gravité.'],'flu-ofsp-17'),
(['Des myalgies et une toux prouvent-elles influenza ?','Non, elles rendent le diagnostic compatible.','La confirmation moléculaire est utile lorsque l’identification du virus change la conduite.'],'flu-ssi-definition flu-ssi-tests'),
(['Une saturation inférieure à 92 % est-elle un simple détail si le patient a une PCR positive ?','Non, elle entre dans les signaux SSI adultes conduisant à envisager l’hospitalisation.','Le diagnostic viral n’annule pas le retentissement respiratoire.'],'flu-ssi-alarmes'),
(['Le seuil de 22 respirations par minute et celui de 30 ont-ils le même usage ?','Non, le premier participe à la décision de bilan inflammatoire, le second figure dans les critères de gravité.','Ils proviennent de branches différentes de la recommandation SSI adulte.'],'flu-ssi-tests flu-ssi-alarmes'),
(['Un test antigénique rapide négatif exclut-il la grippe chez l’adulte ?','Non ; la SSI ne recommande pas cette méthode pour influenza dans cette population.','Une méthode moléculaire est privilégiée si le résultat détermine un antiviral.'],'flu-ssi-tests'),
(['Faut-il prescrire un antibiotique à toute grippe confirmée ?','Non, il faut une probabilité suffisante de complication bactérienne.','Les risques de résistance et d’effets indésirables ne sont pas justifiés par la seule infection virale.'],'flu-ssi-antibiotiques-non'),
(['Un patient de 80 kg reçoit-il 40 ou 80 mg de Xofluza en comprimés ?','La notice prévoit une dose unique orale de 80 mg à partir de 80 kg.','La borne ≥80 kg appartient à la catégorie supérieure ; le tableau AIPS doit être lu exactement.'],'aips-flu-xofluza-4'),
(['Les comprimés de Xofluza sont-ils dosés comme la suspension chez un enfant de moins de 20 kg ?','Non, la suspension possède une dose pondérale et les comprimés ne constituent pas la ligne correspondante.','La forme et le poids doivent être associés à l’indication d’âge et de risque.'],'aips-flu-xofluza-3 aips-flu-xofluza-4'),
(['Peut-on administrer le baloxavir avec un complément de fer ou de calcium ?','La prise concomitante doit être évitée.','Les cations polyvalents peuvent réduire la concentration de baloxavir.'],'aips-flu-xofluza-7'),
(['Tamiflu 75 mg une fois par jour correspond-il au traitement usuel adulte ?','Non, le traitement usuel est deux fois par jour pendant cinq jours ; une fois par jour appartient notamment à la prophylaxie.','Confondre l’indication expose à une erreur de rythme et de durée.'],'aips-flu-tamiflu-4'),
(['Une clairance de 45 mL/min permet-elle la dose usuelle d’oseltamivir ?','La notice prévoit pour le traitement 30 mg deux fois par jour pendant cinq jours dans la plage supérieure à 30 jusqu’à 60 mL/min.','L’adaptation dépend de la fonction rénale et de l’indication.'],'aips-flu-tamiflu-4'),
(['La dose Tamiflu du nourrisson décrite pour une pandémie s’applique-t-elle automatiquement à la grippe saisonnière ?','Non, ce cadre particulier ne doit pas être transposé.','La notice ne fournit pas la même autorisation générale avant un an.'],'aips-flu-tamiflu-3 aips-flu-tamiflu-4'),
(['La présence de cytokines pro-inflammatoires justifie-t-elle une corticothérapie antigrippale systématique ?','Non, le mécanisme ne démontre pas un bénéfice thérapeutique.','La SSI et l’OMS ne recommandent pas cet usage routinier dans les cadres décrits.'],'flu-pathogenese flu-ssi-symptomatique flu-oms-diagnostic'),
(['Quatre grammes de paracétamol constituent-ils une cible pour tous les adultes ?','Non, c’est un plafond usuel qui doit être abaissé dans plusieurs terrains.','Le rein, le foie, la déshydratation, la malnutrition et les autres produits pris modifient la sécurité.'],'aips-flu-dafalgan-4 aips-flu-dafalgan-5 aips-flu-dafalgan-6'),
(['Peut-on diviser un comprimé Dafalgan de 1 g pour improviser une dose pédiatrique ?','La notice précise que son sillon ne sert pas à réduire la dose de moitié.','Il faut une forme et une dose adaptées au poids, avec l’intervalle et le plafond appropriés.'],'aips-flu-dafalgan-4'),
(['Une fatigue persistante impose-t-elle un deuxième antiviral ?','Pas automatiquement ; l’ECDC décrit une fatigue pouvant durer plusieurs semaines.','La décision repose sur la réévaluation clinique et la recherche de complication, non sur la seule persistance d’un symptôme.'],'flu-ecdc-definition flu-ssi-alarmes'),
(['La vaccination antigrippale évite-t-elle tous les syndromes grippaux ?','Non, elle ne protège pas contre tous les virus respiratoires et son efficacité varie.','La distinction entre influenza et syndrome grippal reste nécessaire après vaccination.'],'flu-ofsp-36 flu-ofsp-37'),
(['Les 50 000 à 250 000 consultations suisses représentent-elles toutes les infections annuelles ?','Non, ce sont des estimations de consultations rapportées par l’OFSP à partir de Sentinella.','Le dénominateur et le système de surveillance ne permettent pas cette conversion.'],'flu-ofsp-22')]))
